from django.db import models
from django.contrib.auth.models import AbstractUser

# Create your models here.

class User(AbstractUser):
    #id auto generated 
    description = models.CharField(max_length=512,blank=False,default="default_description")

class Team(models.Model):
    name = models.CharField(max_length=256,  primary_key=True,blank=False,default="default_team_name")
    createdBy = models.ForeignKey(User, on_delete=models.CASCADE,default=0)

class Task(models.Model):
    #auto generated 
    status = models.BooleanField(blank=False)
    createdBy = models.ForeignKey(User, on_delete=models.CASCADE)
    parent = models.ForeignKey('self', on_delete=models.CASCADE, null=True, blank=True)

    # generated by form
    isPrivate = models.BooleanField(blank=False)
    title = models.CharField(max_length=64,blank=False)
    description = models.CharField(max_length=512)


    def __str__(self):
        return f"""Titre: {self.title}\n
        Statut: {self.status}\n
        Description: {self.description}\n
        PrivateStatus: {self.isPrivate}\n
        """

class AssignTeamToTask(models.Model):
    #id auto generated
    team = models.ForeignKey(Team, on_delete=models.CASCADE)
    task = models.ForeignKey(Task, on_delete=models.CASCADE)

class AssignUserToTask(models.Model):
    user = models.ForeignKey(User, on_delete=models.CASCADE)
    task = models.ForeignKey(Task, on_delete=models.CASCADE)

class AssignUserToTeam(models.Model):
    user = models.ForeignKey(User, on_delete=models.CASCADE)
    team = models.ForeignKey(Team, on_delete=models.CASCADE)